<?php
declare(strict_types=1);
function eventnest_editor_admin():bool{return function_exists('auth_current_user') && ($u=auth_current_user()) && $u['Role']==='admin' && $u['UserStatus']==='active';}
function eventnest_public_copy(string $key,string $fallback):string{try{$s=eventnest_db()->prepare('SELECT Content FROM PUBLIC_COPY WHERE CopyKey=?');$s->execute([$key]);return $s->fetchColumn()?:$fallback;}catch(Throwable $e){return $fallback;}}
function eventnest_inline_copy(string $key,string $fallback):void{if(!eventnest_editor_admin())return;?><form class="inline-editor content-card" hidden method="post" action="<?= escape_html(eventnest_url('admin-panel/content.php')) ?>"><?php eventnest_csrf_field(); ?><input type="hidden" name="copy_key" value="<?= escape_html($key) ?>"><label>Introduction<textarea name="content" maxlength="1000" required><?= escape_html(eventnest_public_copy($key,$fallback)) ?></textarea></label><button class="btn btn-blue">Save</button><button type="reset" class="btn btn-outline" data-editor-cancel>Cancel</button></form><?php }
function eventnest_inline_category(?array $category):void{if(!eventnest_editor_admin())return;?><form hidden class="inline-editor content-card" method="post" enctype="multipart/form-data" action="<?= escape_html(eventnest_url('admin-panel/categories.php')) ?>" data-confirm="Save this career-field change?"><?php eventnest_csrf_field(); ?><input type="hidden" name="inline" value="1"><input type="hidden" name="action" value="<?= $category?'edit':'create' ?>"><input type="hidden" name="category_id" value="<?= (int)($category['CategoryID']??0) ?>"><h3><?= $category?'Edit career field':'Add career field' ?></h3><label>Name<input name="name" maxlength="100" value="<?= escape_html($category['CategoryName']??'') ?>" required></label><label>Description<textarea name="description" maxlength="5000"><?= escape_html($category['Description']??'') ?></textarea></label><label>Banner image<input type="file" name="category_image" accept=".jpg,.jpeg,.png,.webp" data-media-preview></label><div data-upload-preview></div><button class="btn btn-blue">Save</button><button class="btn btn-outline" type="reset" data-editor-cancel>Cancel</button></form><?php }
function eventnest_content_toolbar():void{if(!eventnest_editor_admin())return;?><div class="content-toolbar"><span id="editing-label" role="status"></span><button type="button" id="editing-pen" aria-label="Content editing" aria-expanded="false">&#9998;</button><button type="button" id="editing-exit" hidden>Exit editing</button><a href="<?= escape_html(eventnest_url('career-fields.php')) ?>">Career fields</a></div><script src="<?= escape_html(eventnest_url('scripts/content-editor.js')) ?>" defer></script><?php }
